export type DiffType = 'equal' | 'insert' | 'delete' | 'replace';

export interface DiffLine {
  type: DiffType;
  oldLine: string | null;
  newLine: string | null;
  oldNum: number | null;
  newNum: number | null;
}

// Myers diff algorithm on line arrays
function lcs(a: string[], b: string[]): number[][] {
  const m = a.length;
  const n = b.length;
  // Build LCS table
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp;
}

function backtrack(dp: number[][], a: string[], b: string[], i: number, j: number): DiffLine[] {
  if (i === 0 && j === 0) return [];
  if (i > 0 && j > 0 && a[i - 1] === b[j - 1]) {
    return [...backtrack(dp, a, b, i - 1, j - 1), { type: 'equal', oldLine: a[i - 1], newLine: b[j - 1], oldNum: i, newNum: j }];
  }
  if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
    return [...backtrack(dp, a, b, i, j - 1), { type: 'insert', oldLine: null, newLine: b[j - 1], oldNum: null, newNum: j }];
  }
  return [...backtrack(dp, a, b, i - 1, j), { type: 'delete', oldLine: a[i - 1], newLine: null, oldNum: i, newNum: null }];
}

export function diffLines(original: string, modified: string): DiffLine[] {
  const a = original.split('\n');
  const b = modified.split('\n');

  // For large inputs, limit to avoid stack overflow
  if (a.length > 2000 || b.length > 2000) {
    return simpleDiff(a, b);
  }

  const dp = lcs(a, b);
  const raw = backtrack(dp, a, b, a.length, b.length);

  // Merge consecutive delete+insert into replace
  const result: DiffLine[] = [];
  let i = 0;
  while (i < raw.length) {
    if (
      raw[i].type === 'delete' &&
      i + 1 < raw.length &&
      raw[i + 1].type === 'insert'
    ) {
      result.push({
        type: 'replace',
        oldLine: raw[i].oldLine,
        newLine: raw[i + 1].newLine,
        oldNum: raw[i].oldNum,
        newNum: raw[i + 1].newNum,
      });
      i += 2;
    } else {
      result.push(raw[i]);
      i++;
    }
  }
  return result;
}

// Fallback for large inputs
function simpleDiff(a: string[], b: string[]): DiffLine[] {
  const result: DiffLine[] = [];
  const maxLen = Math.max(a.length, b.length);
  for (let i = 0; i < maxLen; i++) {
    if (i >= a.length) {
      result.push({ type: 'insert', oldLine: null, newLine: b[i], oldNum: null, newNum: i + 1 });
    } else if (i >= b.length) {
      result.push({ type: 'delete', oldLine: a[i], newLine: null, oldNum: i + 1, newNum: null });
    } else if (a[i] === b[i]) {
      result.push({ type: 'equal', oldLine: a[i], newLine: b[i], oldNum: i + 1, newNum: i + 1 });
    } else {
      result.push({ type: 'replace', oldLine: a[i], newLine: b[i], oldNum: i + 1, newNum: i + 1 });
    }
  }
  return result;
}

export function diffStats(lines: DiffLine[]) {
  let added = 0, removed = 0, changed = 0;
  for (const l of lines) {
    if (l.type === 'insert') added++;
    else if (l.type === 'delete') removed++;
    else if (l.type === 'replace') changed++;
  }
  return { added, removed, changed };
}
